CREATE FUNCTION "centinela"."k_margen_pct"(dia date) RETURNS TABLE ("linea" text, "margen_pct" numeric, "margen_pct_base" numeric, "caida_pts" numeric, "ventas" numeric, "margen_minimo_pct" numeric, "ventas_mes_prom" numeric, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."linea"::text AS "linea", round("nucleo"."margen_pct"::numeric, 2)::numeric AS "margen_pct", round("nucleo"."margen_pct_base"::numeric, 2)::numeric AS "margen_pct_base", round("nucleo"."caida_pts"::numeric, 2)::numeric AS "caida_pts", "nucleo"."ventas"::numeric AS "ventas", "nucleo"."margen_minimo_pct"::numeric AS "margen_minimo_pct", round("nucleo"."ventas_mes_prom"::numeric, 0)::numeric AS "ventas_mes_prom", round((((greatest("nucleo"."margen_pct_base", "nucleo"."margen_minimo_pct")::numeric - "nucleo"."margen_pct"::numeric)::numeric / NULLIF(100::numeric, 0))::numeric * "nucleo"."ventas"::numeric)::numeric, 0)::numeric AS "pesos_en_riesgo" FROM (WITH periodos AS (SELECT "productos"."linea" AS "linea", date_trunc(''week'', "pedidos"."fecha")::date AS periodo, (sum((("pedidos_detalle"."valor_neto"::numeric - ("pedidos_detalle"."cantidad"::numeric * "pedidos_detalle"."costo_unitario"::numeric)::numeric)::numeric * 100::numeric))::numeric::numeric / NULLIF(sum("pedidos_detalle"."valor_neto")::numeric::numeric, 0)) AS valor, sum("pedidos_detalle"."valor_neto")::numeric AS "ventas", max("margen_minimo"."margen_minimo_pct") AS "margen_minimo_pct", max("trimestre"."ventas_mes_prom") AS "ventas_mes_prom" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) LEFT JOIN "centinela"."productos" AS "productos" ON "pedidos_detalle"."sku" = "productos"."sku" LEFT JOIN "centinela"."ref_margen_minimo_linea" AS "margen_minimo" ON "productos"."linea" = "margen_minimo"."linea" LEFT JOIN (SELECT "nucleo"."linea"::text AS "linea", "nucleo"."ventas_90d"::numeric AS "ventas_90d", ("nucleo"."ventas_90d"::numeric / NULLIF(3::numeric, 0))::numeric AS "ventas_mes_prom" FROM (SELECT "productos"."linea"::text AS "linea", sum("pedidos_detalle"."valor_neto")::numeric::numeric AS "ventas_90d" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) LEFT JOIN "centinela"."productos" AS "productos" ON "pedidos_detalle"."sku" = "productos"."sku" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."fecha" > CAST(dia AS date) - 90 AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "productos"."linea") AS nucleo) AS "trimestre" ON "trimestre"."linea" = "productos"."linea" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' AND "pedidos"."fecha" >= (date_trunc(''week'', CAST(dia AS date) - 6)::date - 7 * 8) AND "pedidos"."fecha" < (date_trunc(''week'', CAST(dia AS date) - 6)::date + 7) GROUP BY "productos"."linea", date_trunc(''week'', "pedidos"."fecha")::date), entidades AS (SELECT DISTINCT "linea" FROM periodos), marco AS (SELECT "entidades"."linea", serie.periodo, periodos.valor AS valor, coalesce("periodos"."ventas", 0) AS "ventas", "periodos"."margen_minimo_pct" AS "margen_minimo_pct", "periodos"."ventas_mes_prom" AS "ventas_mes_prom" FROM entidades CROSS JOIN (SELECT generate_series((date_trunc(''week'', CAST(dia AS date) - 6)::date - 7 * 8), date_trunc(''week'', CAST(dia AS date) - 6)::date, interval ''1 week'')::date AS periodo) AS serie LEFT JOIN periodos ON "periodos"."linea" IS NOT DISTINCT FROM "entidades"."linea" AND periodos.periodo = serie.periodo) SELECT "marco"."linea"::text AS "linea", max(marco.valor) FILTER (WHERE marco.periodo = date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric AS "margen_pct", avg(marco.valor) FILTER (WHERE marco.periodo < date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric AS "margen_pct_base", (avg(marco.valor) FILTER (WHERE marco.periodo < date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric - max(marco.valor) FILTER (WHERE marco.periodo = date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric)::numeric AS "caida_pts", max("marco"."ventas") FILTER (WHERE marco.periodo = date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric AS "ventas", max("marco"."margen_minimo_pct") FILTER (WHERE marco.periodo = date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric AS "margen_minimo_pct", max("marco"."ventas_mes_prom") FILTER (WHERE marco.periodo = date_trunc(''week'', CAST(dia AS date) - 6)::date)::numeric AS "ventas_mes_prom" FROM marco GROUP BY "marco"."linea") AS nucleo';
