CREATE FUNCTION "centinela"."k_saldo_vencido"(dia date) RETURNS TABLE ("cliente_id" text, "saldo_vencido" numeric, "saldo_abierto" numeric, "max_dias_vencido" integer, "cupo_credito" bigint, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."saldo_vencido"::numeric AS "saldo_vencido", "nucleo"."saldo_abierto"::numeric AS "saldo_abierto", "nucleo"."max_dias_vencido"::integer AS "max_dias_vencido", "nucleo"."cupo_credito"::bigint AS "cupo_credito", "nucleo"."saldo_vencido"::numeric AS "pesos_en_riesgo" FROM (SELECT "facturas"."cliente_id"::text AS "cliente_id", coalesce(sum("facturas"."valor_total") FILTER (WHERE "facturas"."fecha_vencimiento" < CAST(dia AS date)), 0)::numeric::numeric AS "saldo_vencido", sum("facturas"."valor_total")::numeric::numeric AS "saldo_abierto", max((CAST(dia AS date) - "facturas"."fecha_vencimiento"))::integer AS "max_dias_vencido", max("clientes"."cupo_credito")::bigint AS "cupo_credito" FROM "centinela"."facturas" AS "facturas" LEFT JOIN "centinela"."clientes" AS "clientes" ON "facturas"."cliente_id" = "clientes"."cliente_id" AND "clientes"."fecha_alta" <= CAST(dia AS date) WHERE "facturas"."fecha_factura" <= CAST(dia AS date) AND "facturas"."fecha_factura" <= CAST(dia AS date) AND NOT EXISTS (SELECT 1 FROM "centinela"."pagos" AS "pagada" WHERE "pagada"."factura_id" = "facturas"."factura_id" AND "pagada"."fecha_pago" <= CAST(dia AS date)) GROUP BY "facturas"."cliente_id") AS nucleo';
