CREATE FUNCTION "centinela"."k_concentracion_vencida_pct"(dia date) RETURNS TABLE ("cliente_id" text, "saldo_vencido" numeric, "concentracion_vencida_pct" numeric, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."saldo_vencido"::numeric AS "saldo_vencido", round((100 * "nucleo"."saldo_vencido"::numeric / NULLIF(sum("nucleo"."saldo_vencido") OVER (), 0))::numeric, 2)::numeric AS "concentracion_vencida_pct", "nucleo"."saldo_vencido"::numeric AS "pesos_en_riesgo" FROM (SELECT "facturas"."cliente_id"::text AS "cliente_id", coalesce(sum("facturas"."valor_total") FILTER (WHERE "facturas"."fecha_vencimiento" < CAST(dia AS date)), 0)::numeric::numeric AS "saldo_vencido" FROM "centinela"."facturas" AS "facturas" WHERE "facturas"."fecha_factura" <= CAST(dia AS date) AND "facturas"."fecha_factura" <= CAST(dia AS date) AND NOT EXISTS (SELECT 1 FROM "centinela"."pagos" AS "pagada" WHERE "pagada"."factura_id" = "facturas"."factura_id" AND "pagada"."fecha_pago" <= CAST(dia AS date)) GROUP BY "facturas"."cliente_id") AS nucleo';
ALTER FUNCTION "centinela"."k_concentracion_vencida_pct"(date) OWNER TO centinela_propietario;
