CREATE FUNCTION "centinela"."k_dias_pago_prom"(dia date) RETURNS TABLE ("cliente_id" text, "dias_pago_prom" numeric, "dias_pago_prom_base" numeric, "aumento_pct" numeric, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."cliente_id"::text AS "cliente_id", round("nucleo"."dias_pago_prom"::numeric, 1)::numeric AS "dias_pago_prom", round("nucleo"."dias_pago_prom_base"::numeric, 1)::numeric AS "dias_pago_prom_base", "nucleo"."aumento_pct"::numeric AS "aumento_pct", "nucleo"."pesos_en_riesgo"::numeric AS "pesos_en_riesgo" FROM (WITH periodos AS (SELECT "facturas"."cliente_id" AS "cliente_id", date_trunc(''month'', "pagos"."fecha_pago")::date AS periodo, avg(("pagos"."fecha_pago" - "facturas"."fecha_factura"))::numeric AS valor, max("cartera"."saldo_abierto") AS "pesos_en_riesgo" FROM "centinela"."pagos" AS "pagos" LEFT JOIN "centinela"."facturas" AS "facturas" ON "pagos"."factura_id" = "facturas"."factura_id" AND "facturas"."fecha_factura" <= CAST(dia AS date) LEFT JOIN (SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."saldo_abierto"::numeric AS "saldo_abierto" FROM (SELECT "facturas"."cliente_id"::text AS "cliente_id", sum("facturas"."valor_total")::numeric::numeric AS "saldo_abierto" FROM "centinela"."facturas" AS "facturas" WHERE "facturas"."fecha_factura" <= CAST(dia AS date) AND "facturas"."fecha_factura" <= CAST(dia AS date) AND NOT EXISTS (SELECT 1 FROM "centinela"."pagos" AS "pagada" WHERE "pagada"."factura_id" = "facturas"."factura_id" AND "pagada"."fecha_pago" <= CAST(dia AS date)) GROUP BY "facturas"."cliente_id") AS nucleo) AS "cartera" ON "cartera"."cliente_id" = "facturas"."cliente_id" WHERE "pagos"."fecha_pago" <= CAST(dia AS date) AND "pagos"."fecha_pago" >= ((date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date - interval ''1 month'' * 12)::date AND "pagos"."fecha_pago" < ((date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date + interval ''1 month'')::date GROUP BY "facturas"."cliente_id", date_trunc(''month'', "pagos"."fecha_pago")::date), entidades AS (SELECT DISTINCT "cliente_id" FROM periodos), marco AS (SELECT "entidades"."cliente_id", serie.periodo, periodos.valor AS valor, "periodos"."pesos_en_riesgo" AS "pesos_en_riesgo" FROM entidades CROSS JOIN (SELECT generate_series(((date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date - interval ''1 month'' * 12)::date, (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date, interval ''1 month'')::date AS periodo) AS serie LEFT JOIN periodos ON "periodos"."cliente_id" IS NOT DISTINCT FROM "entidades"."cliente_id" AND periodos.periodo = serie.periodo) SELECT "marco"."cliente_id"::text AS "cliente_id", max(marco.valor) FILTER (WHERE marco.periodo = (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date)::numeric AS "dias_pago_prom", avg(marco.valor) FILTER (WHERE marco.periodo < (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date)::numeric AS "dias_pago_prom_base", round(100 * (max(marco.valor) FILTER (WHERE marco.periodo = (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date)::numeric / NULLIF(avg(marco.valor) FILTER (WHERE marco.periodo < (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date)::numeric, 0) - 1), 2) AS "aumento_pct", max("marco"."pesos_en_riesgo") FILTER (WHERE marco.periodo = (date_trunc(''month'', CAST(dia AS date) + 1) - interval ''1 month'')::date)::numeric AS "pesos_en_riesgo" FROM marco GROUP BY "marco"."cliente_id") AS nucleo';
