CREATE FUNCTION "centinela"."k_cobertura_dias"(dia date) RETURNS TABLE ("sku" text, "bodega_id" text, "demanda_prom_30d" numeric, "existencia" integer, "clase_abc" text, "precio_lista" numeric, "pedidos_por_despachar" bigint, "cobertura_dias" numeric, "pedidos_pendientes" bigint, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."sku"::text AS "sku", "nucleo"."bodega_id"::text AS "bodega_id", round("nucleo"."demanda_prom_30d"::numeric, 1)::numeric AS "demanda_prom_30d", "nucleo"."existencia"::integer AS "existencia", "nucleo"."clase_abc"::text AS "clase_abc", "nucleo"."precio_lista"::numeric AS "precio_lista", "nucleo"."pedidos_por_despachar"::bigint AS "pedidos_por_despachar", round(("nucleo"."existencia"::numeric / NULLIF("nucleo"."demanda_prom_30d"::numeric, 0))::numeric, 1)::numeric AS "cobertura_dias", greatest("nucleo"."pedidos_por_despachar", 0)::bigint AS "pedidos_pendientes", round((("nucleo"."demanda_prom_30d"::numeric * ((CASE "nucleo"."clase_abc" WHEN ''A'' THEN 10 WHEN ''B'' THEN 7 END)::numeric - ("nucleo"."existencia"::numeric / NULLIF("nucleo"."demanda_prom_30d"::numeric, 0))::numeric)::numeric)::numeric * "nucleo"."precio_lista"::numeric)::numeric, 0)::numeric AS "pesos_en_riesgo" FROM (SELECT "inventario_diario"."sku"::text AS "sku", "inventario_diario"."bodega_id"::text AS "bodega_id", avg("inventario_diario"."salidas")::numeric::numeric AS "demanda_prom_30d", (array_agg("inventario_diario"."existencia_final" ORDER BY "inventario_diario"."fecha" DESC NULLS LAST))[1]::integer AS "existencia", max("productos"."clase_abc")::text AS "clase_abc", max("precio"."precio_lista")::numeric AS "precio_lista", max("pendientes"."pedidos")::bigint AS "pedidos_por_despachar" FROM "centinela"."inventario_diario" AS "inventario_diario" LEFT JOIN "centinela"."productos" AS "productos" ON "inventario_diario"."sku" = "productos"."sku" LEFT JOIN (SELECT "nucleo"."sku"::text AS "sku", "nucleo"."precio_lista"::numeric AS "precio_lista" FROM (SELECT "lista_precios"."sku"::text AS "sku", (array_agg("lista_precios"."precio_lista" ORDER BY "lista_precios"."fecha_vigencia" DESC NULLS LAST))[1]::numeric AS "precio_lista" FROM "centinela"."lista_precios" AS "lista_precios" WHERE "lista_precios"."fecha_vigencia" <= CAST(dia AS date) GROUP BY "lista_precios"."sku") AS nucleo) AS "precio" ON "precio"."sku" = "inventario_diario"."sku" LEFT JOIN (SELECT "nucleo"."sku"::text AS "sku", "nucleo"."pedidos"::bigint AS "pedidos" FROM (SELECT "pedidos_detalle"."sku"::text AS "sku", count(*)::bigint AS "pedidos" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."fecha" <= CAST(dia AS date) AND NOT EXISTS (SELECT 1 FROM "centinela"."facturas" AS "facturada" WHERE "facturada"."pedido_id" = "pedidos_detalle"."pedido_id" AND "facturada"."fecha_factura" <= CAST(dia AS date)) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos_detalle"."sku") AS nucleo) AS "pendientes" ON "pendientes"."sku" = "inventario_diario"."sku" WHERE "inventario_diario"."fecha" <= CAST(dia AS date) AND "inventario_diario"."fecha" > CAST(dia AS date) - 30 GROUP BY "inventario_diario"."sku", "inventario_diario"."bodega_id") AS nucleo';
