GRANT EXECUTE ON FUNCTION "centinela"."k_cobertura_dias"(date) TO centinela_lector;
DROP FUNCTION IF EXISTS "centinela"."k_variacion_costo_pct"(date);
CREATE FUNCTION "centinela"."k_variacion_costo_pct"(dia date) RETURNS TABLE ("sku" text, "costo_unitario" numeric, "costo_anterior" numeric, "fecha_vigencia" date, "ultimo_cambio_precio" date, "precio_lista" numeric, "unidades_desde_vigencia" numeric, "unidades_mes_prom" numeric, "variacion_pct" numeric, "dias_habiles_sin_traslado" integer, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."sku"::text AS "sku", "nucleo"."costo_unitario"::numeric AS "costo_unitario", "nucleo"."costo_anterior"::numeric AS "costo_anterior", "nucleo"."fecha_vigencia"::date AS "fecha_vigencia", "nucleo"."ultimo_cambio_precio"::date AS "ultimo_cambio_precio", "nucleo"."precio_lista"::numeric AS "precio_lista", "nucleo"."unidades_desde_vigencia"::numeric AS "unidades_desde_vigencia", round("nucleo"."unidades_mes_prom"::numeric, 1)::numeric AS "unidades_mes_prom", round(((("nucleo"."costo_unitario"::numeric / NULLIF("nucleo"."costo_anterior"::numeric, 0))::numeric - 1::numeric)::numeric * 100::numeric)::numeric, 2)::numeric AS "variacion_pct", (CASE WHEN "nucleo"."ultimo_cambio_precio" >= "nucleo"."fecha_vigencia" THEN 0 ELSE (SELECT count(*) FROM generate_series("nucleo"."fecha_vigencia" + 1, CAST(dia AS date), interval ''1 day'') AS habil(d) WHERE extract(isodow FROM habil.d) < 6)::integer END)::integer AS "dias_habiles_sin_traslado", round((("nucleo"."costo_unitario"::numeric - "nucleo"."costo_anterior"::numeric)::numeric * "nucleo"."unidades_desde_vigencia"::numeric)::numeric, 0)::numeric AS "pesos_en_riesgo" FROM (SELECT "costos_proveedor"."sku"::text AS "sku", (array_agg("costos_proveedor"."costo_unitario" ORDER BY "costos_proveedor"."fecha_vigencia" DESC NULLS LAST))[1]::numeric AS "costo_unitario", (array_agg("costos_proveedor"."costo_unitario" ORDER BY "costos_proveedor"."fecha_vigencia" DESC NULLS LAST))[2]::numeric AS "costo_anterior", max("costos_proveedor"."fecha_vigencia")::date AS "fecha_vigencia", max("precio"."ultimo_cambio_precio")::date AS "ultimo_cambio_precio", max("precio"."precio_lista")::numeric AS "precio_lista", max("ventas"."unidades_desde_vigencia")::numeric AS "unidades_desde_vigencia", max("ventas"."unidades_mes_prom")::numeric AS "unidades_mes_prom" FROM "centinela"."costos_proveedor" AS "costos_proveedor" LEFT JOIN (SELECT "nucleo"."sku"::text AS "sku", "nucleo"."ultimo_cambio_precio"::date AS "ultimo_cambio_precio", "nucleo"."precio_lista"::numeric AS "precio_lista" FROM (SELECT "lista_precios"."sku"::text AS "sku", max("lista_precios"."fecha_vigencia")::date AS "ultimo_cambio_precio", (array_agg("lista_precios"."precio_lista" ORDER BY "lista_precios"."fecha_vigencia" DESC NULLS LAST))[1]::numeric AS "precio_lista" FROM "centinela"."lista_precios" AS "lista_precios" WHERE "lista_precios"."fecha_vigencia" <= CAST(dia AS date) GROUP BY "lista_precios"."sku") AS nucleo) AS "precio" ON "precio"."sku" = "costos_proveedor"."sku" LEFT JOIN (SELECT "nucleo"."sku"::text AS "sku", "nucleo"."unidades_desde_vigencia"::numeric AS "unidades_desde_vigencia", "nucleo"."unidades_90d"::numeric AS "unidades_90d", ("nucleo"."unidades_90d"::numeric / NULLIF(3::numeric, 0))::numeric AS "unidades_mes_prom" FROM (SELECT "pedidos_detalle"."sku"::text AS "sku", coalesce(sum("pedidos_detalle"."cantidad") FILTER (WHERE "pedidos"."fecha" >= "vigencia"."fecha_vigencia"), 0)::numeric::numeric AS "unidades_desde_vigencia", coalesce(sum("pedidos_detalle"."cantidad") FILTER (WHERE "pedidos"."fecha" > (CAST(dia AS date) - 90)), 0)::numeric::numeric AS "unidades_90d" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) LEFT JOIN (SELECT "nucleo"."sku"::text AS "sku", "nucleo"."fecha_vigencia"::date AS "fecha_vigencia" FROM (SELECT "costos_proveedor"."sku"::text AS "sku", max("costos_proveedor"."fecha_vigencia")::date AS "fecha_vigencia" FROM "centinela"."costos_proveedor" AS "costos_proveedor" WHERE "costos_proveedor"."fecha_vigencia" <= CAST(dia AS date) GROUP BY "costos_proveedor"."sku") AS nucleo) AS "vigencia" ON "vigencia"."sku" = "pedidos_detalle"."sku" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos_detalle"."sku") AS nucleo) AS "ventas" ON "ventas"."sku" = "costos_proveedor"."sku" WHERE "costos_proveedor"."fecha_vigencia" <= CAST(dia AS date) GROUP BY "costos_proveedor"."sku") AS nucleo';
ALTER FUNCTION "centinela"."k_variacion_costo_pct"(date) OWNER TO centinela_propietario;
REVOKE ALL ON FUNCTION "centinela"."k_variacion_costo_pct"(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "centinela"."k_variacion_costo_pct"(date) TO centinela_lector;
DROP FUNCTION IF EXISTS "centinela"."k_dias_retraso"(date);
CREATE FUNCTION "centinela"."k_dias_retraso"(dia date) RETURNS TABLE ("oc_id" text, "fecha_recibida" date, "fecha_esperada" date, "pesos_en_riesgo" numeric, "recibida" boolean, "dias_retraso" integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."oc_id"::text AS "oc_id", "nucleo"."fecha_recibida"::date AS "fecha_recibida", "nucleo"."fecha_esperada"::date AS "fecha_esperada", "nucleo"."pesos_en_riesgo"::numeric AS "pesos_en_riesgo", ("nucleo"."fecha_recibida" IS NOT NULL)::boolean AS "recibida", (CASE WHEN ("nucleo"."fecha_recibida" IS NOT NULL) THEN greatest(("nucleo"."fecha_recibida" - "nucleo"."fecha_esperada"), 0) ELSE greatest((CAST(dia AS date) - "nucleo"."fecha_esperada"), 0) END)::integer AS "dias_retraso" FROM (SELECT "ordenes_compra"."oc_id"::text AS "oc_id", max((CASE WHEN "ordenes_compra"."fecha_recibida" <= CAST(dia AS date) THEN "ordenes_compra"."fecha_recibida" END))::date AS "fecha_recibida", max("ordenes_compra"."fecha_esperada")::date AS "fecha_esperada", sum(("ordenes_compra"."cantidad"::numeric * "ordenes_compra"."costo_unitario"::numeric))::numeric::numeric AS "pesos_en_riesgo" FROM "centinela"."ordenes_compra" AS "ordenes_compra" WHERE "ordenes_compra"."fecha_oc" <= CAST(dia AS date) GROUP BY "ordenes_compra"."oc_id") AS nucleo';
ALTER FUNCTION "centinela"."k_dias_retraso"(date) OWNER TO centinela_propietario;
REVOKE ALL ON FUNCTION "centinela"."k_dias_retraso"(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "centinela"."k_dias_retraso"(date) TO centinela_lector;
DROP FUNCTION IF EXISTS "centinela"."k_descuento_en_exceso"(date);
CREATE FUNCTION "centinela"."k_descuento_en_exceso"(dia date) RETURNS TABLE ("vendedor_id" text, "semana" date, "descuento_en_exceso" numeric, "exceso_semana_anterior" numeric, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."vendedor_id"::text AS "vendedor_id", "nucleo"."semana"::date AS "semana", round("nucleo"."descuento_en_exceso"::numeric, 0)::numeric AS "descuento_en_exceso", round(max("nucleo"."descuento_en_exceso") OVER (PARTITION BY "nucleo"."vendedor_id" ORDER BY "nucleo"."semana" RANGE BETWEEN interval ''1 week'' PRECEDING AND interval ''1 week'' PRECEDING)::numeric, 0)::numeric AS "exceso_semana_anterior", round("nucleo"."descuento_en_exceso"::numeric, 0)::numeric AS "pesos_en_riesgo" FROM (SELECT "pedidos"."vendedor_id"::text AS "vendedor_id", date_trunc(''week'', "pedidos"."fecha")::date::date AS "semana", sum(((("pedidos_detalle"."cantidad"::numeric * "pedidos_detalle"."precio_unitario"::numeric)::numeric * ("pedidos_detalle"."descuento_pct"::numeric - "topes"."tope_descuento_pct"::numeric)::numeric)::numeric / NULLIF(100::numeric, 0)))::numeric::numeric AS "descuento_en_exceso" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) LEFT JOIN "centinela"."clientes" AS "clientes" ON "pedidos"."cliente_id" = "clientes"."cliente_id" AND "clientes"."fecha_alta" <= CAST(dia AS date) LEFT JOIN "centinela"."ref_topes_descuento" AS "topes" ON "clientes"."segmento" = "topes"."segmento" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' AND "pedidos_detalle"."aprobacion_especial" = ''N'' AND "pedidos_detalle"."descuento_pct" > "topes"."tope_descuento_pct" GROUP BY "pedidos"."vendedor_id", date_trunc(''week'', "pedidos"."fecha")::date) AS nucleo';
ALTER FUNCTION "centinela"."k_descuento_en_exceso"(date) OWNER TO centinela_propietario;
REVOKE ALL ON FUNCTION "centinela"."k_descuento_en_exceso"(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "centinela"."k_descuento_en_exceso"(date) TO centinela_lector;
DROP FUNCTION IF EXISTS "centinela"."k_margen_bruto_negativo"(date);
CREATE FUNCTION "centinela"."k_margen_bruto_negativo"(dia date) RETURNS TABLE ("pedido_id" text, "linea_n" integer, "margen_bruto" numeric, "sku" text, "fecha" date, "pesos_en_riesgo" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "kpi"."pedido_id"::text AS "pedido_id", "kpi"."linea_n"::integer AS "linea_n", "kpi"."margen_bruto"::numeric AS "margen_bruto", "kpi"."sku"::text AS "sku", "kpi"."fecha"::date AS "fecha", "kpi"."pesos_en_riesgo"::numeric AS "pesos_en_riesgo" FROM (SELECT "nucleo"."pedido_id"::text AS "pedido_id", "nucleo"."linea_n"::integer AS "linea_n", "nucleo"."margen_bruto"::numeric AS "margen_bruto", "nucleo"."sku"::text AS "sku", "nucleo"."fecha"::date AS "fecha", (0::numeric - "nucleo"."margen_bruto"::numeric)::numeric AS "pesos_en_riesgo" FROM (SELECT "pedidos_detalle"."pedido_id"::text AS "pedido_id", "pedidos_detalle"."linea_n"::integer AS "linea_n", sum(("pedidos_detalle"."valor_neto"::numeric - ("pedidos_detalle"."cantidad"::numeric * "pedidos_detalle"."costo_unitario"::numeric)::numeric))::numeric::numeric AS "margen_bruto", max("pedidos_detalle"."sku")::text AS "sku", max("pedidos"."fecha")::date AS "fecha" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos_detalle"."pedido_id", "pedidos_detalle"."linea_n") AS nucleo) AS kpi WHERE "kpi"."margen_bruto" < 0';
ALTER FUNCTION "centinela"."k_margen_bruto_negativo"(date) OWNER TO centinela_propietario;
REVOKE ALL ON FUNCTION "centinela"."k_margen_bruto_negativo"(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "centinela"."k_margen_bruto_negativo"(date) TO centinela_lector;
DROP FUNCTION IF EXISTS "centinela"."k_veces_intervalo_habitual"(date);
CREATE FUNCTION "centinela"."k_veces_intervalo_habitual"(dia date) RETURNS TABLE ("cliente_id" text, "pedidos" bigint, "ultima_compra" date, "primera_compra" date, "pesos_en_riesgo" numeric, "intervalo_prom_dias" numeric, "dias_sin_comprar" integer, "veces_intervalo_habitual" numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS 'SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."pedidos"::bigint AS "pedidos", "nucleo"."ultima_compra"::date AS "ultima_compra", "nucleo"."primera_compra"::date AS "primera_compra", round("nucleo"."pesos_en_riesgo"::numeric, 0)::numeric AS "pesos_en_riesgo", round((("nucleo"."ultima_compra" - "nucleo"."primera_compra")::numeric / NULLIF(("nucleo"."pedidos"::numeric - 1::numeric)::numeric, 0))::numeric, 1)::numeric AS "intervalo_prom_dias", (CAST(dia AS date) - "nucleo"."ultima_compra")::integer AS "dias_sin_comprar", round(((CAST(dia AS date) - "nucleo"."ultima_compra")::numeric / NULLIF((("nucleo"."ultima_compra" - "nucleo"."primera_compra")::numeric / NULLIF(("nucleo"."pedidos"::numeric - 1::numeric)::numeric, 0))::numeric, 0))::numeric, 1)::numeric AS "veces_intervalo_habitual" FROM (SELECT "pedidos"."cliente_id"::text AS "cliente_id", count(*)::bigint AS "pedidos", max("pedidos"."fecha")::date AS "ultima_compra", min("pedidos"."fecha")::date AS "primera_compra", max("compras"."valor_mes_prom")::numeric AS "pesos_en_riesgo" FROM "centinela"."pedidos" AS "pedidos" LEFT JOIN (SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."valor_6m"::numeric AS "valor_6m", ("nucleo"."valor_6m"::numeric / NULLIF(6::numeric, 0))::numeric AS "valor_mes_prom" FROM (SELECT "pedidos"."cliente_id"::text AS "cliente_id", coalesce(sum("pedidos_detalle"."valor_neto") FILTER (WHERE "pedidos"."fecha" > ("ultima"."ultima_compra" - interval ''1 month'' * 6)::date), 0)::numeric::numeric AS "valor_6m" FROM "centinela"."pedidos_detalle" AS "pedidos_detalle" LEFT JOIN "centinela"."pedidos" AS "pedidos" ON "pedidos_detalle"."pedido_id" = "pedidos"."pedido_id" AND "pedidos"."fecha" <= CAST(dia AS date) LEFT JOIN (SELECT "nucleo"."cliente_id"::text AS "cliente_id", "nucleo"."ultima_compra"::date AS "ultima_compra" FROM (SELECT "pedidos"."cliente_id"::text AS "cliente_id", max("pedidos"."fecha")::date AS "ultima_compra" FROM "centinela"."pedidos" AS "pedidos" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos"."cliente_id") AS nucleo) AS "ultima" ON "ultima"."cliente_id" = "pedidos"."cliente_id" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos"."cliente_id") AS nucleo) AS "compras" ON "compras"."cliente_id" = "pedidos"."cliente_id" WHERE "pedidos"."fecha" <= CAST(dia AS date) AND "pedidos"."estado" <> ''Cancelado'' GROUP BY "pedidos"."cliente_id") AS nucleo';
ALTER FUNCTION "centinela"."k_veces_intervalo_habitual"(date) OWNER TO centinela_propietario;
REVOKE ALL ON FUNCTION "centinela"."k_veces_intervalo_habitual"(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "centinela"."k_veces_intervalo_habitual"(date) TO centinela_lector;
